INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Easy', 'Which keyword is used to define a function in Python?', 'func', 'def', 'function', 'define', 'B', 'Functions are defined using the ''def'' keyword.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Easy', 'What is the output of type([])?', '<class ''list''>', '<class ''dict''>', '<class ''tuple''>', '<class ''set''>', 'A', 'An empty [] literal creates a list object.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Easy', 'Which of these is a mutable data type in Python?', 'tuple', 'string', 'list', 'int', 'C', 'Lists can be changed after creation, unlike tuples, strings and ints.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Easy', 'How do you start a comment in Python?', '//', '#', '/*', '--', 'B', 'Python single-line comments start with ''#''.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Easy', 'What does len(''hello'') return?', '4', '5', '6', 'Error', 'B', '''hello'' has 5 characters.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Easy', 'Which operator is used for exponentiation?', '^', '**', '%%', 'exp()', 'B', 'The ** operator raises a number to a power.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Medium', 'What is the difference between a list and a tuple?', 'Lists are immutable, tuples are mutable', 'Lists are mutable, tuples are immutable', 'Both are mutable', 'Both are immutable', 'B', 'Lists can be modified after creation; tuples cannot.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Medium', 'What does the ''self'' keyword represent in a class method?', 'The class itself', 'The instance of the class', 'A static variable', 'A global variable', 'B', '''self'' refers to the current instance of the class.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Medium', 'Which module is used for regular expressions in Python?', 'regex', 're', 'pyregex', 'regexp', 'B', 'The built-in ''re'' module provides regex support.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Medium', 'What is a list comprehension used for?', 'Sorting a list', 'Creating a list in a concise way', 'Deleting list elements', 'Copying a dictionary', 'B', 'List comprehensions provide a compact syntax to build lists.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Medium', 'What does the ''is'' operator check?', 'Value equality', 'Type equality', 'Identity (same object in memory)', 'Length equality', 'C', '''is'' checks whether two references point to the same object.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Medium', 'What will `print(3 // 2)` output?', '1.5', '1', '2', 'Error', 'B', '''//'' performs floor (integer) division, so 3//2 = 1.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Medium', 'Which of the following creates a virtual environment?', 'python -m venv env', 'python venv create', 'pip venv env', 'python --venv', 'A', '''python -m venv env'' creates a new virtual environment named env.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Medium', 'What is the purpose of the __init__ method?', 'To destroy an object', 'To initialize a new object''s attributes', 'To import a module', 'To define a static method', 'B', '__init__ is the constructor called when creating a new object.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Hard', 'What is a Python decorator?', 'A design pattern for UI', 'A function that modifies another function''s behavior', 'A type of loop', 'A built-in data type', 'B', 'Decorators wrap functions to extend their behavior without modifying their code.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Hard', 'What does the Global Interpreter Lock (GIL) do?', 'Speeds up multi-threaded CPU-bound code', 'Allows only one thread to execute Python bytecode at a time', 'Locks global variables only', 'Prevents memory leaks', 'B', 'The GIL ensures only one thread executes Python bytecode at once in CPython.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Hard', 'What is the output of `[x for x in range(3)] + [x for x in range(2)]`?', '[0,1,2,0,1]', '[0,1,0,1,2]', 'Error', '[0,1,2]', 'A', 'List concatenation appends the second list to the first: [0,1,2]+[0,1]=[0,1,2,0,1].');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Hard', 'What does `yield` do inside a function?', 'Ends the function immediately', 'Turns the function into a generator returning values lazily', 'Raises an exception', 'Imports a module', 'B', '''yield'' makes a function a generator, producing values one at a time.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Hard', 'What is the difference between deep copy and shallow copy?', 'No difference', 'Shallow copy copies nested objects too', 'Deep copy recursively copies nested objects, shallow copy does not', 'Deep copy is faster', 'C', 'copy.deepcopy() duplicates nested objects, while copy.copy() only copies the outer object.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Python', 'Hard', 'Which of these correctly handles multiple exceptions in one except block?', 'except (TypeError, ValueError):', 'except TypeError, ValueError:', 'except [TypeError, ValueError]:', 'except TypeError and ValueError:', 'A', 'Multiple exceptions are caught using a tuple in the except clause.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Easy', 'Which keyword is used to create a class in Java?', 'class', 'Class', 'new', 'struct', 'A', 'Classes are declared using the lowercase ''class'' keyword.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Easy', 'What is the entry point method of a Java application?', 'start()', 'main()', 'run()', 'init()', 'B', 'Execution begins from the public static void main(String[] args) method.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Easy', 'Which of these is not a Java primitive type?', 'int', 'boolean', 'String', 'char', 'C', 'String is a class/object type, not a primitive.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Easy', 'How do you create a single-line comment in Java?', '#', '//', '<!-- -->', '**', 'B', 'Single-line comments in Java start with ''//''.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Easy', 'Which keyword is used to inherit a class in Java?', 'implements', 'extends', 'inherits', 'super', 'B', 'A class inherits another class using the ''extends'' keyword.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Easy', 'What is the default value of a boolean variable in Java?', 'true', 'false', '0', 'null', 'B', 'Uninitialized instance boolean fields default to false.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Medium', 'What is the difference between ''=='' and ''.equals()'' for objects?', 'No difference', '''=='' compares references, ''.equals()'' compares values by default logic', '''.equals()'' compares references only', '''=='' compares values only', 'B', '''=='' checks reference equality while ''.equals()'' can be overridden to compare content.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Medium', 'Which collection class does not allow duplicate elements?', 'ArrayList', 'LinkedList', 'HashSet', 'Vector', 'C', 'HashSet is backed by a hash table and does not allow duplicates.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Medium', 'What does the ''final'' keyword mean when applied to a variable?', 'It can be changed once', 'Its value cannot be reassigned after initialization', 'It is a static variable', 'It is deleted after use', 'B', 'A ''final'' variable''s reference/value cannot change once assigned.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Medium', 'What is method overloading?', 'Same method name, different implementation in subclass', 'Same method name, different parameter list in same class', 'Same method name and parameters in different classes', 'Overriding a method', 'B', 'Overloading means multiple methods share a name but differ in parameters.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Medium', 'Which interface must a class implement to be used with the ''for-each'' loop?', 'Comparable', 'Iterable', 'Runnable', 'Serializable', 'B', 'Iterable provides the iterator() method required for for-each loops.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Medium', 'What is the purpose of the ''static'' keyword?', 'Creates instance-level members', 'Creates class-level members shared across instances', 'Prevents inheritance', 'Marks a method as abstract', 'B', 'Static members belong to the class rather than any specific instance.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Medium', 'Which exception is thrown when dividing an integer by zero in Java?', 'NullPointerException', 'ArithmeticException', 'NumberFormatException', 'ClassCastException', 'B', 'Integer division by zero throws ArithmeticException at runtime.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Hard', 'What is the difference between an abstract class and an interface (Java 8+)?', 'No difference', 'Abstract classes can have constructors and state; interfaces primarily define behavior (can have default methods)', 'Interfaces can have constructors', 'Abstract classes cannot have methods', 'B', 'Abstract classes support state and constructors, interfaces focus on contracts with optional default methods.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Hard', 'What does the JVM garbage collector primarily manage?', 'CPU scheduling', 'Automatic memory management by reclaiming unused objects', 'Thread priorities', 'File I/O', 'B', 'The garbage collector automatically frees memory of objects no longer referenced.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Hard', 'What is a functional interface in Java?', 'An interface with multiple abstract methods', 'An interface with exactly one abstract method, usable with lambdas', 'A class with static methods only', 'An interface with no methods', 'B', 'Functional interfaces have a single abstract method and can be implemented via lambda expressions.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Hard', 'What does ''synchronized'' keyword achieve in multithreading?', 'Improves performance always', 'Ensures only one thread accesses a block/method at a time', 'Creates a new thread', 'Stops garbage collection', 'B', '''synchronized'' provides mutual exclusion, preventing concurrent access issues.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Hard', 'Which of the following best describes Java''s memory model regarding the Heap?', 'Stores local primitive variables only', 'Stores objects and is shared across threads', 'Stores only static methods', 'Is cleared every method call', 'B', 'The heap stores objects and class instances and is shared among all threads.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Hard', 'What is the purpose of the ''volatile'' keyword?', 'Makes a variable constant', 'Ensures visibility of changes to a variable across threads', 'Improves compile-time speed', 'Disables garbage collection for the variable', 'B', '''volatile'' ensures that reads/writes to a variable are visible to all threads immediately.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Java', 'Hard', 'What will happen if a subclass does not implement all abstract methods of an interface?', 'Compiles with warning', 'Compilation error unless the subclass is also declared abstract', 'Runs but throws exception at runtime', 'Nothing, it is optional', 'B', 'A non-abstract class must implement all abstract methods, or a compile error occurs.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Easy', 'Which data structure uses FIFO (First In First Out) order?', 'Stack', 'Queue', 'Tree', 'Graph', 'B', 'A Queue processes elements in the order they were added: first in, first out.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Easy', 'Which data structure uses LIFO (Last In First Out) order?', 'Queue', 'Stack', 'Array', 'Linked List', 'B', 'A Stack removes the most recently added element first.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Easy', 'What is the time complexity of accessing an element by index in an array?', 'O(n)', 'O(log n)', 'O(1)', 'O(n^2)', 'C', 'Arrays support direct indexed access in constant time.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Easy', 'Which data structure is best for representing hierarchical data?', 'Array', 'Stack', 'Tree', 'Queue', 'C', 'Trees naturally represent parent-child hierarchical relationships.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Easy', 'What does a linked list node typically contain?', 'Only data', 'Data and a pointer/reference to the next node', 'Only a pointer', 'An index and a key', 'B', 'Each node stores data plus a reference to the next node in the list.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Easy', 'Which operation adds an element to the top of a stack?', 'Enqueue', 'Push', 'Insert', 'Append', 'B', '''Push'' adds a new element to the top of a stack.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Medium', 'What is the average time complexity of searching in a balanced Binary Search Tree?', 'O(1)', 'O(log n)', 'O(n)', 'O(n log n)', 'B', 'A balanced BST has height log n, so search takes O(log n) on average.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Medium', 'Which data structure is used to implement recursion internally?', 'Queue', 'Stack', 'Heap', 'Graph', 'B', 'Function calls are managed using a call stack.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Medium', 'What is a hash collision?', 'Two keys mapping to the same index in a hash table', 'A hash table becoming full', 'Deleting the wrong key', 'Hashing failing entirely', 'A', 'A collision occurs when two different keys hash to the same bucket/index.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Medium', 'What is the time complexity of inserting an element at the beginning of an array of size n?', 'O(1)', 'O(log n)', 'O(n)', 'O(n^2)', 'C', 'Inserting at the start requires shifting all n existing elements.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Medium', 'Which traversal visits nodes in a Binary Search Tree in sorted order?', 'Preorder', 'Postorder', 'In-order', 'Level-order', 'C', 'In-order traversal (left, root, right) visits BST nodes in ascending order.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Medium', 'What is a ''heap'' data structure primarily used for?', 'Sorting strings', 'Efficiently finding the min or max element', 'Storing key-value pairs', 'Representing graphs', 'B', 'A heap maintains the min or max element accessible in O(1) time.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Medium', 'What is the space complexity of an adjacency matrix for a graph with V vertices?', 'O(V)', 'O(V + E)', 'O(V^2)', 'O(E)', 'C', 'An adjacency matrix requires a V x V grid, giving O(V^2) space.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Hard', 'What is the time complexity of Dijkstra''s algorithm using a binary heap?', 'O(V^2)', 'O(E log V)', 'O(V + E)', 'O(E^2)', 'B', 'Using a binary heap, Dijkstra''s algorithm runs in O(E log V) time.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Hard', 'What is the worst-case time complexity of QuickSort?', 'O(n log n)', 'O(n)', 'O(n^2)', 'O(log n)', 'C', 'QuickSort degrades to O(n^2) when the pivot selection is consistently poor (e.g. sorted input with naive pivot).');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Hard', 'What is a self-balancing binary search tree example?', 'Linked List', 'AVL Tree', 'Array', 'Hash Map', 'B', 'AVL Trees automatically rebalance to keep O(log n) height.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Hard', 'What is the amortized time complexity of appending to a dynamic array (like Python list)?', 'O(n)', 'O(1) amortized', 'O(log n)', 'O(n^2)', 'B', 'Dynamic arrays double capacity occasionally, giving O(1) amortized append time.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Hard', 'In a Trie data structure, what is primarily stored at each node?', 'A full word', 'A character and links to child nodes', 'An integer index', 'A hash value', 'B', 'Trie nodes represent characters, with paths forming words.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Hard', 'What technique does a hash table use to resolve collisions via linked lists at each bucket?', 'Open addressing', 'Separate chaining', 'Linear probing', 'Double hashing', 'B', 'Separate chaining stores colliding elements in a linked list at the same bucket.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Data Structures', 'Hard', 'What is the key property of a min-heap?', 'Every parent node is greater than its children', 'Every parent node is smaller than or equal to its children', 'It is always a complete binary search tree', 'Elements are stored in sorted array order', 'B', 'In a min-heap, each parent is less than or equal to its children, keeping the minimum at the root.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Easy', 'What does HTML stand for?', 'Hyper Text Markup Language', 'High Text Markup Language', 'Hyper Transfer Markup Language', 'Home Tool Markup Language', 'A', 'HTML stands for Hyper Text Markup Language.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Easy', 'Which tag is used to link an external CSS file?', '<style>', '<script>', '<link>', '<css>', 'C', 'The <link> tag with rel=''stylesheet'' loads an external CSS file.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Easy', 'Which CSS property controls text size?', 'font-weight', 'text-size', 'font-size', 'text-style', 'C', '''font-size'' sets the size of the text.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Easy', 'Which HTML tag is used to create a hyperlink?', '<link>', '<a>', '<href>', '<hyper>', 'B', 'The anchor tag <a> defines a hyperlink.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Easy', 'Which symbol is used to select a class in CSS?', '#', '*', '.', '&', '.', 'In CSS, a period (.) prefixes a class selector.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Easy', 'What does CSS stand for?', 'Cascading Style Sheets', 'Creative Style Sheets', 'Computer Style Sheets', 'Colorful Style Sheets', 'A', 'CSS stands for Cascading Style Sheets.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Medium', 'What is the purpose of the ''box-sizing: border-box'' CSS property?', 'Removes borders', 'Includes padding and border within the element''s total width/height', 'Hides the box model', 'Adds margin automatically', 'B', 'border-box makes width/height include padding and border, simplifying sizing.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Medium', 'What is the difference between ''let'' and ''var'' in JavaScript?', 'No difference', '''let'' is block-scoped, ''var'' is function-scoped', '''var'' is block-scoped, ''let'' is function-scoped', '''let'' cannot be reassigned', 'B', '''let'' respects block scope while ''var'' is scoped to the nearest function.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Medium', 'What does the ''fetch()'' function in JavaScript return?', 'A synchronous value', 'A Promise', 'A callback', 'An XMLHttpRequest object', 'B', 'fetch() returns a Promise that resolves to the Response object.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Medium', 'Which HTTP method is typically used to submit new data to a server?', 'GET', 'POST', 'HEAD', 'OPTIONS', 'B', 'POST is commonly used to send new data to create a resource.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Medium', 'What is the CSS Flexbox property used to align items along the main axis?', 'align-items', 'justify-content', 'flex-direction', 'align-self', 'B', '''justify-content'' aligns flex items along the main axis.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Medium', 'What does ''responsive design'' primarily refer to?', 'Fast server response times', 'Layouts that adapt to different screen sizes', 'Using only JavaScript', 'Avoiding CSS entirely', 'B', 'Responsive design ensures a site adapts well across various devices and screen sizes.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Medium', 'What is the purpose of the ''async'' attribute on a <script> tag?', 'Loads the script only after user interaction', 'Downloads script in parallel and executes it as soon as it''s ready, without blocking HTML parsing', 'Prevents the script from ever running', 'Forces synchronous loading', 'B', '''async'' allows the script to download in parallel and run immediately once ready.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Hard', 'What problem does CORS (Cross-Origin Resource Sharing) address?', 'Improves page load speed', 'Controls whether a browser allows requests to a different origin than the page''s own', 'Encrypts HTTP traffic', 'Compresses JavaScript files', 'B', 'CORS is a browser security mechanism that governs cross-origin HTTP requests.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Hard', 'What is the main advantage of using JWT (JSON Web Tokens) for authentication?', 'They are always encrypted', 'They are stateless and can carry claims without server-side session storage', 'They never expire', 'They replace HTTPS', 'B', 'JWTs let servers verify identity without maintaining server-side session state.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Hard', 'What is ''event delegation'' in JavaScript?', 'Attaching an event listener to a parent to handle events from child elements via bubbling', 'Removing all event listeners', 'Delegating events to a web worker', 'Using async/await for events', 'A', 'Event delegation leverages event bubbling to handle events at a common ancestor.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Hard', 'What is the purpose of a CSS preprocessor like SASS?', 'Runs JavaScript in CSS', 'Adds features like variables, nesting, and mixins that compile to plain CSS', 'Replaces HTML', 'Compresses images', 'B', 'SASS extends CSS with programming features and compiles down to standard CSS.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Hard', 'What does the term ''critical rendering path'' refer to?', 'The database query path', 'The sequence of steps the browser takes to convert HTML/CSS/JS into pixels on screen', 'The server routing logic', 'The CI/CD deployment pipeline', 'B', 'It describes how a browser turns HTML, CSS, and JS into rendered pixels.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Hard', 'What is the main difference between REST and GraphQL APIs?', 'REST uses a single endpoint with flexible queries, GraphQL uses many endpoints', 'GraphQL uses a single endpoint letting clients request exactly the data they need, REST typically has multiple fixed endpoints', 'They are identical', 'GraphQL cannot use HTTP', 'B', 'GraphQL exposes one endpoint with client-specified queries, while REST usually has multiple resource-based endpoints.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Web Development', 'Hard', 'What is ''debouncing'' used for in JavaScript event handling?', 'Increasing event frequency', 'Limiting how often a function executes by delaying it until after a pause in events', 'Preventing all click events', 'Sorting event listeners', 'B', 'Debouncing delays execution until the event stream pauses, reducing excessive calls (e.g. on scroll/resize).');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Easy', 'Which SQL statement is used to retrieve data from a database?', 'GET', 'SELECT', 'FETCH', 'RETRIEVE', 'B', 'SELECT is used to query and retrieve data from a database table.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Easy', 'Which clause is used to filter rows in SQL?', 'ORDER BY', 'WHERE', 'GROUP BY', 'HAVING', 'B', 'WHERE filters rows based on specified conditions.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Easy', 'Which SQL keyword is used to sort results?', 'SORT', 'ORDER BY', 'ARRANGE', 'GROUP BY', 'B', 'ORDER BY sorts the result set by one or more columns.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Easy', 'Which statement is used to add new rows to a table?', 'INSERT INTO', 'ADD ROW', 'CREATE', 'UPDATE', 'A', 'INSERT INTO adds new rows of data into a table.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Easy', 'Which keyword removes duplicate rows from a result set?', 'UNIQUE', 'DISTINCT', 'REMOVE DUP', 'FILTER', 'B', 'DISTINCT removes duplicate rows from the SELECT results.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Easy', 'Which SQL command is used to remove a table entirely from the database?', 'DELETE', 'DROP TABLE', 'REMOVE TABLE', 'TRUNCATE ONLY', 'B', 'DROP TABLE permanently deletes the table structure and its data.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Medium', 'What is the difference between DELETE and TRUNCATE?', 'No difference', 'DELETE removes rows with optional WHERE and can be rolled back; TRUNCATE removes all rows and resets identity, harder to roll back', 'TRUNCATE is slower', 'DELETE always removes the whole table', 'B', 'DELETE supports conditions/transactions; TRUNCATE quickly clears the whole table and resets auto-increment.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Medium', 'What does a PRIMARY KEY constraint ensure?', 'Values can repeat', 'Uniquely identifies each row and disallows NULLs', 'Allows NULL values', 'Sorts the table', 'B', 'A primary key uniquely identifies each row and cannot contain NULL values.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Medium', 'What is a FOREIGN KEY used for?', 'Encrypting data', 'Linking a column to the primary key of another table to maintain referential integrity', 'Indexing text columns', 'Removing duplicate rows', 'B', 'A foreign key enforces a link between two tables'' related columns.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Medium', 'Which JOIN returns rows only when there is a match in both tables?', 'LEFT JOIN', 'RIGHT JOIN', 'INNER JOIN', 'FULL OUTER JOIN', 'C', 'INNER JOIN returns only rows that have matching values in both tables.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Medium', 'What does the GROUP BY clause do?', 'Sorts rows alphabetically', 'Groups rows sharing a value so aggregate functions can be applied per group', 'Removes NULL rows', 'Joins two tables', 'B', 'GROUP BY groups rows with the same values for use with aggregate functions like COUNT or SUM.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Medium', 'What is the purpose of an index in a database?', 'Encrypts data', 'Speeds up data retrieval at the cost of extra storage and slower writes', 'Prevents duplicate values', 'Compresses tables', 'B', 'Indexes speed up read queries by allowing faster lookups, though they add overhead to writes.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Medium', 'What does the HAVING clause do differently from WHERE?', 'HAVING filters rows before grouping, WHERE after', 'HAVING filters groups after aggregation, WHERE filters rows before aggregation', 'They are identical', 'HAVING only works with INSERT', 'B', 'WHERE filters individual rows before grouping; HAVING filters aggregated groups afterward.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Hard', 'What isolation level prevents dirty reads but may still allow non-repeatable reads?', 'READ UNCOMMITTED', 'READ COMMITTED', 'REPEATABLE READ', 'SERIALIZABLE', 'B', 'READ COMMITTED prevents dirty reads but non-repeatable reads can still occur.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Hard', 'What is database normalization primarily used for?', 'Increasing redundancy', 'Reducing data redundancy and improving data integrity by organizing tables', 'Encrypting the schema', 'Speeding up all writes unconditionally', 'B', 'Normalization organizes data to minimize redundancy and dependency issues.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Hard', 'What does a database transaction''s ''ACID'' property ''Atomicity'' guarantee?', 'Data is always encrypted', 'The transaction executes fully or not at all', 'Transactions run in parallel', 'Data is automatically indexed', 'B', 'Atomicity ensures a transaction is all-or-nothing.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Hard', 'What is a common cause of SQL injection vulnerabilities?', 'Using parameterized queries', 'Concatenating raw user input directly into SQL query strings', 'Using stored procedures', 'Using an ORM exclusively', 'B', 'Injection occurs when untrusted input is concatenated directly into SQL statements instead of being parameterized.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Hard', 'What is the purpose of a database view?', 'Physically duplicates table data permanently', 'A virtual table based on the result of a stored query, simplifying complex queries', 'Only used for indexing', 'Replaces triggers', 'B', 'A view is a saved query presented as a virtual table, without duplicating underlying data.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Hard', 'In a many-to-many relationship, what is typically used to model it in a relational database?', 'A single shared column', 'A junction/association table with foreign keys to both tables', 'Nested tables', 'A CHECK constraint', 'B', 'A junction table with two foreign keys models many-to-many relationships in SQL.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('SQL', 'Hard', 'What does ''EXPLAIN'' (or query execution plan) help a developer do?', 'Encrypt a query', 'Understand how the database engine will execute a query for performance tuning', 'Format SQL syntax', 'Backup the database', 'B', 'EXPLAIN shows the query plan, helping identify performance bottlenecks like missing indexes.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Easy', 'What does ''phishing'' refer to?', 'A firewall technique', 'Tricking users into revealing sensitive information via fake communications', 'A type of encryption', 'A network protocol', 'B', 'Phishing uses deceptive messages to trick victims into revealing sensitive data.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Easy', 'What is a firewall primarily used for?', 'Storing passwords', 'Monitoring and controlling incoming/outgoing network traffic based on rules', 'Encrypting emails', 'Compiling code', 'B', 'A firewall filters network traffic according to defined security rules.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Easy', 'What does ''HTTPS'' add to standard HTTP?', 'Faster loading only', 'Encryption via TLS/SSL for secure communication', 'Better SEO only', 'Larger file size limits', 'B', 'HTTPS encrypts data in transit using TLS/SSL.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Easy', 'What is malware?', 'Legitimate software', 'Malicious software designed to harm or exploit systems', 'A hardware component', 'A network cable', 'B', 'Malware is software intentionally designed to cause damage or unauthorized access.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Easy', 'What is two-factor authentication (2FA)?', 'Using two different passwords', 'Requiring two independent forms of verification to log in', 'Encrypting data twice', 'Logging in twice a day', 'B', '2FA requires a second independent verification factor beyond just a password.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Easy', 'What does ''VPN'' stand for?', 'Virtual Private Network', 'Verified Public Network', 'Virtual Protocol Node', 'Very Private Node', 'A', 'VPN stands for Virtual Private Network, which creates an encrypted tunnel for traffic.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Medium', 'What is a ''brute-force attack''?', 'Exploiting a software bug', 'Systematically trying many password combinations until the correct one is found', 'Intercepting network packets', 'Installing a rootkit', 'B', 'Brute-force attacks try many credential combinations to guess the correct one.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Medium', 'What does ''SQL Injection'' exploit?', 'Weak Wi-Fi encryption', 'Improperly sanitized user input in database queries', 'Outdated browsers only', 'Physical server access', 'B', 'SQL Injection exploits unsanitized input that gets executed as part of a SQL query.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Medium', 'What is the principle of ''least privilege''?', 'Giving users maximum access for convenience', 'Granting users only the minimum access necessary to perform their tasks', 'Removing all access controls', 'Sharing admin credentials among teams', 'B', 'Least privilege limits access rights to only what''s needed for a task, reducing risk.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Medium', 'What is Cross-Site Scripting (XSS)?', 'A database attack', 'Injecting malicious scripts into webpages viewed by other users', 'A DNS attack', 'A firewall bypass technique only', 'B', 'XSS involves injecting malicious client-side scripts into trusted websites.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Medium', 'What does ''hashing'' a password (as opposed to encrypting) provide?', 'Reversible transformation for later retrieval', 'A one-way transformation making it infeasible to recover the original password', 'Faster login speed only', 'Automatic password strength', 'B', 'Hashing is a one-way function; unlike encryption, hashed data isn''t meant to be reversed.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Medium', 'What is a ''man-in-the-middle'' (MITM) attack?', 'Malware that deletes files', 'An attacker secretly intercepting/altering communication between two parties', 'A denial-of-service attack', 'A social engineering call', 'B', 'In MITM, an attacker covertly relays and possibly alters communication between two parties who believe they''re talking directly.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Medium', 'What is the purpose of ''salting'' passwords before hashing?', 'Making passwords shorter', 'Adding random data to each password before hashing to prevent rainbow table attacks', 'Speeding up hashing', 'Allowing passwords to be reversed', 'B', 'Salting adds unique random data per password, defeating precomputed rainbow table attacks.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Hard', 'What does a Distributed Denial-of-Service (DDoS) attack aim to do?', 'Steal encrypted data', 'Overwhelm a target system with traffic from multiple sources to make it unavailable', 'Slowly extract database records', 'Bypass two-factor authentication', 'B', 'DDoS floods a target with traffic from many sources to exhaust its resources and cause downtime.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Hard', 'What is the purpose of a Content Security Policy (CSP) header?', 'Encrypts HTTP headers', 'Restricts which sources of content (scripts, styles, etc.) a browser is allowed to load, mitigating XSS', 'Compresses web pages', 'Improves SEO ranking', 'B', 'CSP lets a site define allowed content sources to reduce risks like XSS.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Hard', 'What distinguishes symmetric from asymmetric encryption?', 'No difference', 'Symmetric uses one shared key for encryption/decryption; asymmetric uses a public/private key pair', 'Asymmetric is always faster', 'Symmetric cannot be broken', 'B', 'Symmetric encryption uses the same key for both operations; asymmetric uses separate public and private keys.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Hard', 'What is a ''zero-day'' vulnerability?', 'A vulnerability patched immediately', 'A previously unknown flaw exploited before the vendor has released a fix', 'A vulnerability that only affects day-old software', 'An outdated CVE entry', 'B', 'A zero-day is an unpatched, often undisclosed vulnerability actively exploitable by attackers.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Hard', 'What does ''CSRF'' (Cross-Site Request Forgery) exploit?', 'Weak passwords', 'A user''s authenticated session to perform unwanted actions on a site without their consent', 'DNS misconfiguration', 'Unencrypted Wi-Fi only', 'B', 'CSRF tricks an authenticated user''s browser into submitting unwanted requests to a trusted site.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Hard', 'What is ''penetration testing''?', 'Automated antivirus scanning', 'Authorized simulated attacks on a system to find and fix security weaknesses', 'Installing a firewall', 'Encrypting a database', 'B', 'Pen testing involves ethically simulating attacks to discover vulnerabilities before malicious actors do.');
INSERT INTO mcq_questions (category, difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES ('Cybersecurity', 'Hard', 'What is the main goal of ''defense in depth''?', 'Relying on a single strong security control', 'Layering multiple independent security controls so failure of one doesn''t compromise the whole system', 'Reducing the number of security tools', 'Only securing the network perimeter', 'B', 'Defense in depth uses multiple layered controls so no single point of failure compromises overall security.');
